/// 24 판의 점들을 받은 사각형에 맞춰 그린다.
struct EnsoShape: Shape {
    var points: [(CGFloat, CGFloat)] = EnsoGeometry.stroke
    func path(in rect: CGRect) -> Path {
        let k = min(rect.width, rect.height) / 24
        var p = Path()
        for (i, (x, y)) in points.enumerated() {
            let pt = CGPoint(x: rect.minX + x * k, y: rect.minY + y * k)
            if i == 0 { p.move(to: pt) } else { p.addLine(to: pt) }
        }
        p.closeSubpath()
        return p
    }
}
